package fetvisuals.modules.visuals;
import fetvisuals.module.*; import fetvisuals.module.settings.*; import fetvisuals.render.RenderUtils; import net.minecraft.client.MinecraftClient; import net.minecraft.client.gui.DrawContext;
public final class CustomCrosshair extends fetvisuals.module.Module {private final NumberSetting size=add(new NumberSetting("Size",5,2,14,1));private final NumberSetting gap=add(new NumberSetting("Gap",3,0,10,1));private final ColorSetting color=add(new ColorSetting("Color",0xFFE9D9FF));public CustomCrosshair(){super("CustomCrosshair","Minimal custom crosshair",Category.VISUALS);}public void onHud(DrawContext c,float d){int cx=MinecraftClient.getInstance().getWindow().getScaledWidth()/2,cy=MinecraftClient.getInstance().getWindow().getScaledHeight()/2,s=size.get().intValue(),g=gap.get().intValue(),col=color.get();RenderUtils.rect(c,cx-1,cy-g-s,2,s,col);RenderUtils.rect(c,cx-1,cy+g,2,s,col);RenderUtils.rect(c,cx-g-s,cy-1,s,2,col);RenderUtils.rect(c,cx+g,cy-1,s,2,col);}}
